fn finish_restyle(
    &self,
    context: &mut StyleContext<Self>,
    data: &mut ElementData,
    mut new_styles: ResolvedElementStyles,
    important_rules_changed: bool,
) -> RestyleHint {
    self.process_animations(
        context,
        &mut data.styles,
        &mut new_styles,
        important_rules_changed,
    );

    // First of all, update the styles.
    let old_styles = data.set_styles(new_styles);

    let new_primary_style = data.styles.primary.as_ref().unwrap();

    let mut child_restyle_hint = RestyleHint::empty();
    let is_root = new_primary_style
        .flags
        .contains(ComputedValueFlags::IS_ROOT_ELEMENT_STYLE);

    let device = context.shared.stylist.device();
    let new_font_size = new_primary_style.get_font().slow_clone_font_size();
    let new_container_type = *new_primary_style.get_container_type();

    let old_style = old_styles.primary.as_ref();
    let old_font_size = old_style.map(|s| s.get_font().slow_clone_font_size());
    let font_size_changed = old_font_size.is_none_or(|fs| fs != new_font_size);

    let line_height_likely_changed =
        font_size_changed || Self::line_height_likely_changed(old_style, new_primary_style);

    // Update root font-relative units. If any of these unit values changed
    // since last time, ensure that we recascade the entire tree.
    if is_root {
        debug_assert!(self.owner_doc_matches_for_testing(device));
        device.set_root_style(new_primary_style);

        // Update root font size for rem units
        if font_size_changed {
            let size = new_font_size.computed_size();
            device.set_root_font_size(new_primary_style.effective_zoom.unzoom(size.px()));
        }

        // Update root line height for rlh units
        if line_height_likely_changed {
            let new_line_height = device
                .calc_line_height(
                    new_primary_style.get_font(),
                    new_primary_style.writing_mode,
                    None,
                )
                .0;
            device.set_root_line_height(
                new_primary_style
                    .effective_zoom
                    .unzoom(new_line_height.px()),
            );
        }

        // Update root font metrics for rcap, rch, rex, ric units. Since querying
        // font metrics can be an expensive call, they are only updated if these
        // units are used in the document.
        if device.used_root_font_metrics() && device.update_root_font_metrics() {
            child_restyle_hint |= RestyleHint::RESTYLE_IF_AFFECTED_BY_WM_OR_ANCESTOR_FONT;
        }
    }

    if font_size_changed || line_height_likely_changed {
        child_restyle_hint |= RestyleHint::RESTYLE_IF_AFFECTED_BY_WM_OR_ANCESTOR_FONT;
    }

    if context.shared.stylist.quirks_mode() == QuirksMode::Quirks
        && self.is_html_document_body_element()
    {
        // NOTE(emilio): We _could_ handle dynamic changes to it if it
        // changes and before we reach our children the cascade stops,
        // but we don't track right now whether we use the document body
        // color, and nobody else handles that properly anyway.
        let device = context.shared.stylist.device();

        // Needed for the "inherit from body" quirk.
        let text_color = *new_primary_style.get_inherited_text().get_color();
        device.set_body_text_color(text_color);
    }

    // Don't accumulate damage if we're in the final animation traversal.
    if context
        .shared
        .traversal_flags
        .contains(TraversalFlags::FinalAnimationTraversal)
    {
        return RestyleHint::RECASCADE_SELF;
    }

    if self.has_animations(context.shared) {
        tasks.insert(UpdateAnimationsTasks::EFFECT_PROPERTIES);
        if important_rules_changed {
            tasks.insert(UpdateAnimationsTasks::CASCADE_RESULTS);
        }
        if new_styles
            .primary_style()
            .is_display_property_changed_from_none(old_values.as_deref())
        {
            tasks.insert(UpdateAnimationsTasks::DISPLAY_CHANGED_FROM_NONE);
        }
    }

    if !tasks.is_empty() {
        let task = crate::context::SequentialTask::update_animations(
            *self,
            before_change_style,
            tasks,
        );
        context.thread_local.tasks.push(task);
    }
}

fn needs_to_recascade_self(hint: RestyleHint, style: &ComputedValues) -> bool {
    if hint.intersects(RestyleHint::RECASCADE_SELF) {
        return true;
    }
    if hint.intersects(RestyleHint::RECASCADE_SELF_IF_INHERIT_RESET_STYLE)
        && style
            .flags
            .contains(ComputedValueFlags::INHERITS_RESET_STYLE)
    {
        return true;
    }
    if hint.intersects(RestyleHint::RESTYLE_IF_AFFECTED_BY_WM_OR_ANCESTOR_FONT)
        && style
            .flags
            .contains(ComputedValueFlags::USES_FONT_OR_WM_RELATIVE_UNITS)
    {
        return true;
    }
    false
}

pub extern "C" fn Servo_GetComputedKeyframeValues(
    keyframes: &nsTArray<structs::Keyframe>,
    element: &RawGeckoElement,
    pseudo_type: PseudoStyleType,
    style: &ComputedValues,
    raw_data: &PerDocumentStyleData,
    computed_keyframes: &mut nsTArray<structs::ComputedKeyframeValues>,
) -> bool {
    use style::applicable_declarations::CascadePriority;
    use style::properties::{
        CustomDeclarationValue, KeyframeCustomPropertiesBuilder, PropertyDeclaration,
    };
    use style::properties_and_values::value::CustomAnimatedValue;
    let data = raw_data.borrow();
    let element = GeckoElement(element);
    let pseudo = PseudoElement::from_pseudo_type(pseudo_type, None);
    let parent_element = if pseudo.is_none() {
        element.inheritance_parent()
    } else {
        Some(element)
    };
    let parent_data = parent_element.as_ref().and_then(|e| e.borrow_data());
    let parent_style = parent_data
        .as_ref()
        .map(|d| d.styles.primary())
        .map(|x| &**x);

    let container_size_query =
        ContainerSizeQuery::for_element(element, parent_style, pseudo.is_some());
    let mut conditions = Default::default();
    let mut tree_counting_caches = TreeCountingCaches::default();
    let mut context = create_context_for_animation(
        &data,
        &style,
        parent_style,
        /* for_smil_animation = */ false,
        &mut conditions,
        container_size_query,
        &element,
        &mut tree_counting_caches,
    );

    let restriction = pseudo.map_or(PropertyFlags::empty(), |p| p.property_restriction());

    let global_style_data = &*GLOBAL_STYLE_DATA;
    let guard = global_style_data.shared_lock.read();
    let default_values = data.default_computed_values();
    let mut attribute_tracker = AttributeTracker::new(&element);

    for (index, keyframe) in keyframes.iter().enumerate() {
        let ref mut animation_values = computed_keyframes[index];

        let mut seen = PropertyDeclarationIdSet::default();
        let mut iter = PrioritizedPropertyIter::new(&keyframe.mPropertyValues);

        // FIXME (bug 1883255): This is pretty much a hack. Instead, the AnimatedValue should be
        // better integrated in the cascade.
        {
            let mut builder = KeyframeCustomPropertiesBuilder::new(
                &data.stylist,
                &mut context,
                style.custom_properties().clone(),
            );
            let priority = CascadePriority::same_tree_author_normal_at_root_layer();
            for property in &mut iter {
                let is_custom = match PropertyId::from_gecko_css_property_id(&property.mProperty) {
                    Some(PropertyId::Custom(..)) => true,
                    _ => false,
                };
                if !is_custom {
                    break; // Custom props are guaranteed to sort earlier.
                }
                if property.mServoDeclarationBlock.mRawPtr.is_null() {
                    continue;
                }
                let declarations = unsafe { &*property.mServoDeclarationBlock.mRawPtr };
                let guard = declarations.read_with(&guard);
                for decl in guard.normal_declaration_iter() {
                    if let PropertyDeclaration::Custom(ref declaration) = *decl {
                        builder.cascade(&mut context, declaration, priority);
                    }
                }
            }
            iter.reset();
            for property in &mut iter {
                if simulate_compute_values_failure(property)
                    || property.mServoDeclarationBlock.mRawPtr.is_null()
                {
                    continue;
                }
                let declarations = unsafe { &*property.mServoDeclarationBlock.mRawPtr };
                let guard = declarations.read_with(&guard);
                for declaration in guard.normal_declaration_iter() {
                    if let PropertyDeclaration::WithVariables(declaration) = declaration {
                        builder.prepare_attributes(
                            &mut context,
                            &declaration.value,
                            &mut attribute_tracker,
                        );
                    }
                }
            }
            iter.reset();
            builder.build(&mut context, &mut attribute_tracker);
        };

        let mut property_index = 0;
        for property in iter {
            if simulate_compute_values_failure(property) {
                continue;
            }

            let mut maybe_append_animation_value =
                |property: PropertyDeclarationId, value: Option<AnimationValue>| {
                    debug_assert!(!property.is_logical());
                    debug_assert!(property.is_animatable());

                    if property == PropertyDeclarationId::Longhand(LonghandId::Display)
                        && !static_prefs::pref!("layout.css.display-animations.enabled")
                    {
                        return;
                    }

                    // Skip restricted properties
                    if !restriction.is_empty() && !property.flags().contains(restriction) {
                        return;
                    }

                    if seen.contains(property) {
                        return;
                    }
                    seen.insert(property);

                    animation_values.push(structs::PropertyStyleAnimationValuePair {
                        mProperty: property.to_gecko_css_property_id(),
                        mValue: structs::AnimationValue {
                            mServo: value.map_or(structs::RefPtr::null(), |v| {
                                structs::RefPtr::from_arc(Arc::new(v))
                            }),
                        },
                    });
                    property_index += 1;
                };

            if property.mServoDeclarationBlock.mRawPtr.is_null() {
                if let Some(prop) =
                    OwnedPropertyDeclarationId::from_gecko_css_property_id(&property.mProperty)
                {
                    maybe_append_animation_value(prop.as_borrowed(), None);
                }
                continue;
            }

            let declarations = unsafe { &*property.mServoDeclarationBlock.mRawPtr };
            let guard = declarations.read_with(&guard);
            for declaration in guard.normal_declaration_iter() {
                if let PropertyDeclaration::Custom(custom) = declaration
                    && matches!(custom.value, CustomDeclarationValue::Unparsed(_))
                {
                    let registration = data.stylist.get_custom_property_registration(&custom.name);
                    if !registration.is_universal() {
                        let value = context
                            .builder
                            .custom_properties()
                            .get(registration, &custom.name);
                        let value = AnimationValue::Custom(CustomAnimatedValue::from_computed(
                            &custom.name,
                            value,
                        ));
                        maybe_append_animation_value(value.id(), Some(value.clone()));
                        continue;
                    }
                }

                if let Some(value) = AnimationValue::from_declaration(
                    declaration,
                    &mut context,
                    style,
                    &default_values,
                    &mut attribute_tracker,
                ) {
                    maybe_append_animation_value(value.id(), Some(value.clone()));
                }
            }
        }
    }
    attribute_tracker.references.is_some()
}

pub fn root_font_size(&self) -> Length {
    self.used_root_font_size.store(true, Ordering::Relaxed);
    Length::new(f32::from_bits(self.root_font_size.load(Ordering::Relaxed)))
}

/// Set the font size of the root element (for rem), in zoom-independent CSS pixels.
pub fn set_root_font_size(&self, size: f32) {
    self.root_font_size.store(size.to_bits(), Ordering::Relaxed)
}

/// Get the line height of the root element (for rlh)
pub fn root_line_height(&self) -> Length {
    self.used_root_line_height.store(true, Ordering::Relaxed);
    Length::new(f32::from_bits(
        self.root_line_height.load(Ordering::Relaxed),
    ))
}

/// Set the line height of the root element (for rlh), in zoom-independent CSS pixels.
pub fn set_root_line_height(&self, size: f32) {
    self.root_line_height
        .store(size.to_bits(), Ordering::Relaxed);
}

void EffectCompositor::UpdateEffectProperties(
    const ComputedStyle* aStyle, Element* aElement,
    const PseudoStyleRequest& aPseudoRequest) {
  EffectSet* effectSet = EffectSet::Get(aElement, aPseudoRequest);
  if (!effectSet) {
    return;
  }

  // Style context (Gecko) or computed values (Stylo) change might cause CSS
  // cascade level, e.g removing !important, so we should update the cascading
  // result.
  effectSet->MarkCascadeNeedsUpdate();

  for (KeyframeEffect* effect : *effectSet) {
    effect->UpdateProperties(aStyle);
  }
}
